        "onboardingV2.review.t1.author": "Camille, 22 de ani",
        "onboardingV2.review.t2.quote": "10 minute în tren dimineața și am ceva de vorbit noaptea. Sincer cuplat.",
        "onboardingV2.review.t2.author": "Yanis, 27 de ani",
        "onboardingV2.review.t3.quote": "Tot am urât «să recapitulăm», dar aici intră singur. Memoria mă surprinde.",
        "onboardingV2.review.t3.author": "Inès, 19 ani",
        "onboardingV2.review.t4.quote": "Îmi schimb derularea nesfârșită cu o lecție. Într-o lună, oamenii din jurul meu au observat diferența.",
        "onboardingV2.review.t4.author": "Toma, 31 de ani",
        "onboardingV2.review.t5.quote": "În sfârșit, o aplicație care mă face să simt că merg înainte, fără să pierd timpul. Îl deschid în fiecare zi.",
        "onboardingV2.review.t5.author": "Sara, 26 de ani",
        "onboardingV2.review.t6.quote": "Testele spațiate sunt magice: îmi amintesc lucruri pe care le-am învățat cu săptămâni în urmă fără măcar să încerc.",
        "onboardingV2.review.t6.author": "Malik, 23 de ani",
