        "onboardingV2.transform.tapHint": "Tik om door te gaan",
        "onboardingV2.exams.title": "Ze verbeterden hun cijfers",
        "onboardingV2.exams.quote1": "\"Dankzij Sophia is mijn geschiedenisgemiddelde dit semester met 3 punten gestegen.\"",
        "onboardingV2.exams.author1": "Thomas, leerling",
        "onboardingV2.exams.quote2": "\"Ik revisie 10 minuten per dag en mijn cijfers gingen echt omhoog.\"",
        "onboardingV2.exams.author2": "Inès, laatste jaar",
        "onboardingV2.exams.quote3": "\"De quizzen hielpen me de essentie te onthouden vóór mijn examens.\"",
        "onboardingV2.exams.author3": "Camille, universiteit",
        "onboardingV2.exams.quote4": "\"Perfect om onderweg te herhalen. Mijn docenten merkten het verschil.\"",
        "onboardingV2.exams.author4": "Yanis, middelbare school",
        "onboardingV2.rightPlace.title": "Je bent hier goed",
        "onboardingV2.rightPlace.ofUsers": "van gebruikers",
        "onboardingV2.rightPlace.caption": "…met dit doel echte vooruitgang boeken met Sophia.",
        "onboardingV2.swipe.title": "Voor jou uitgekozen cursussen",
        "onboardingV2.swipe.subtitle": "Veeg naar rechts wat je interesseert.",
        "onboardingV2.swipe.like": "Leuk",
        "onboardingV2.swipe.nope": "Nee",
        "onboardingV2.swipe.noted": "Gedaan!",
        "onboardingV2.phone.title": "Hoeveel tijd besteed jij aan je telefoon?",
        "onboardingV2.phone.perDay": "per dag",
        "onboardingV2.weeks.title": "Dat zijn %d weken per jaar",
        "onboardingV2.weeks.subtitle": "Dit is jouw jaar. In het rood: tijd op je scherm.",
        "onboardingV2.weeks.caption": "Stel je voor wat je in een fractie van die tijd zou kunnen leren.",
        "onboardingV2.review.title": "Dit is wat onze gebruikers denken",
        "onboardingV2.review.appStore": "in de App Store",
        "onboardingV2.review.quote": "\"Vroeger bracht ik zeven uur per dag door op mijn telefoon. Nu slechts 40 minuten met Sophia, en ik voel me elke week slimmer.\"",
        "onboardingV2.review.author": "Lea, 24",
        "onboardingV2.review.t1.quote": "Omdat ik minder scroll en Sophia gebruik, heb ik het gevoel dat ik me eigenlijk veel meer herinner.",
        "onboardingV2.review.t1.author": "Kamille, 22",
        "onboardingV2.review.t2.quote": "'s Ochtends tien minuten in de trein en 's avonds heb ik iets om over te praten. Eerlijk gezegd verslaafd.",
        "onboardingV2.review.t2.author": "Yanis, 27",
        "onboardingV2.review.t3.quote": "Ik heb altijd een hekel gehad aan «blokken», maar dit blijft gewoon hangen. Mijn geheugen verrast me.",
        "onboardingV2.review.t3.author": "Inès, 19",
        "onboardingV2.review.t4.quote": "Ik ruil mijn eindeloze scrollen in voor een lesje. Binnen een maand merkten de mensen om mij heen het verschil.",
        "onboardingV2.review.t4.author": "Thomas, 31",
        "onboardingV2.review.t5.quote": "Eindelijk een app die me het gevoel geeft dat ik vooruit ga en geen tijd verspil. Ik open het elke dag.",
        "onboardingV2.review.t5.author": "Sara, 26",
        "onboardingV2.review.t6.quote": "Gespreide quizzen zijn magisch: ik herinner me dingen die ik weken geleden heb geleerd zonder zelfs maar te proberen.",
        "onboardingV2.review.t6.author": "Malik, 23",
