        "onboardingV2.exams.title": "Javították az osztályzatukat",
        "onboardingV2.exams.quote1": "\"Sophiának köszönhetően a történelem átlagom 3 ponttal emelkedett ezen a féléven.\"",
        "onboardingV2.exams.author1": "Tamás, diák",
        "onboardingV2.exams.quote2": "\"Naponta 10 percet javítok, és az osztályzataim nagyon felmentek.\"",
        "onboardingV2.exams.author2": "Inès, felső tagozat",
        "onboardingV2.exams.quote3": "– A vetélkedők segítettek emlékeznem a lényeges dolgokra a vizsgáim előtt.",
        "onboardingV2.exams.author3": "Camille, egyetem",
        "onboardingV2.exams.quote4": "\"Tökéletes az útközbeni átdolgozáshoz. A tanáraim észrevették a különbséget.\"",
        "onboardingV2.exams.author4": "Yanis, középiskola",
        "onboardingV2.rightPlace.title": "Jó helyen vagy",
        "onboardingV2.rightPlace.ofUsers": "felhasználók közül",
        "onboardingV2.rightPlace.caption": "…ezzel a céllal valós előrelépést kell elérni Sophiával.",
        "onboardingV2.swipe.title": "Neked válogatott tanfolyamok",
        "onboardingV2.swipe.subtitle": "Csúsztasd jobbra, ami érdekel.",
        "onboardingV2.swipe.like": "Tetszik",
        "onboardingV2.swipe.nope": "Dehogy",
        "onboardingV2.swipe.noted": "Megvan!",
        "onboardingV2.phone.title": "Mennyi időt töltesz a telefonodon?",
        "onboardingV2.phone.perDay": "naponta",
        "onboardingV2.weeks.title": "Ez évente %d hét",
        "onboardingV2.weeks.subtitle": "Ez a te éved. Piros: a képernyőn töltött idő.",
        "onboardingV2.weeks.caption": "Képzeld el, mit tanulhatsz meg ennek az időnek a töredékével.",
        "onboardingV2.review.title": "Íme, mit gondolnak a felhasználók",
        "onboardingV2.review.appStore": "az App Store-ban",
        "onboardingV2.review.quote": "\"Régebben napi 7 órát töltöttem a telefonomon. Most csak 40 percet töltök Sophiával, és hétről hétre okosabbnak érzem magam.\"",
        "onboardingV2.review.author": "Léa, 24 éves",
        "onboardingV2.review.t1.quote": "Mivel kevesebbet görgetek, és a Sophiát használom, úgy érzem, sokkal többre emlékszem.",
        "onboardingV2.review.t1.author": "Kamilla, 22 éves",
        "onboardingV2.review.t2.quote": "Reggel 10 perc vonatozás, és éjszaka van miről beszélnem. Őszintén kiakadva.",
        "onboardingV2.review.t2.author": "Yanis, 27 éves",
        "onboardingV2.review.t3.quote": "Mindig utáltam a «magolást», de ez magától megmarad. A memóriám meglep.",
        "onboardingV2.review.t3.author": "Inès, 19",
        "onboardingV2.review.t4.quote": "A végtelen görgetésemet leckére cserélem. Egy hónap alatt a körülöttem lévők észrevették a különbséget.",
        "onboardingV2.review.t4.author": "Tamás, 31 éves",
        "onboardingV2.review.t5.quote": "Végre egy alkalmazás, amitől úgy érzem, hogy haladok előre, nem vesztegetem az időt. Minden nap kinyitom.",
        "onboardingV2.review.t5.author": "Sarah, 26 éves",
        "onboardingV2.review.t6.quote": "A szóközönkénti kvízek varázslatosak: emlékszem olyan dolgokra, amelyeket hetekkel ezelőtt tanultam, anélkül, hogy megpróbáltam volna.",
        "onboardingV2.review.t6.author": "Malik, 23 éves",
